const state = {
  user: { name: 'Ravi', address: { city: 'Pune', pin: '411001' } },
  prefs: { theme: 'dark' }
};

const next = {
  ...state,
  user: {
    ...state.user,
    address: { ...state.user.address, city: 'Delhi' }
  }
};

console.log(state.user.address.city);   // 'Pune'  (original untouched)
console.log(next.user.address.city);    // 'Delhi'
console.log(next.prefs === state.prefs); // true   (shared)
console.log(next.user === state.user);   // false  (copied on the path)

