practice.solution:
function setIn(obj, path, value) {
  if (path.length === 0) return value;
  const [head, ...rest] = path;
  const current = obj == null ? undefined : obj[head];
  const next = setIn(current, rest, value);
  if (obj != null && Object.is(current, next)) return obj;
  if (Array.isArray(obj)) {
    const copy = obj.slice();
    copy[Number(head)] = next;
    return copy;
  }
  return { ...(obj || {}), [head]: next };
}

const lines = stdin.trim().split('\n');
const original = JSON.parse(lines[0]);
const n = parseInt(lines[1], 10);
let state = original;
for (let i = 2; i < 2 + n; i++) {
  const line = lines[i];
  const space = line.indexOf(' ');
  const path = line.slice(0, space).split('.');
  const value = JSON.parse(line.slice(space + 1));
  state = setIn(state, path, value);
}
const changed = Object.keys(state).filter(k => !Object.is(state[k], original[k]));
console.log('changed: ' + (changed.length ? changed.join(',') : 'none'));
console.log(JSON.stringify(state));
console.log(JSON.stringify(original));

